using DriveOS.Modules.CurriculumPedagogy.Domain.LicenseCategories;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.CurriculumPedagogy.Infrastructure.Persistence.Configurations;
internal sealed class LicenseCategoryDefinitionConfiguration:IEntityTypeConfiguration<LicenseCategoryDefinition>{public void Configure(EntityTypeBuilder<LicenseCategoryDefinition>b){b.ToTable("license_category_definitions");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new LicenseCategoryDefinitionId(x)).ValueGeneratedNever();b.Property(x=>x.OrganizationId).HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.CountryCode).HasMaxLength(2);b.Property(x=>x.Code).HasMaxLength(30);b.Property(x=>x.Name).HasMaxLength(160);b.Property(x=>x.Description).HasMaxLength(2000);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.ActivatedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.ArchivedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.CreatedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.LastModifiedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.HasIndex(x=>new{x.OrganizationId,x.CountryCode,x.Code}).IsUnique();b.Ignore(x=>x.DomainEvents);}}
